 | InstrumentedANF.TypedAtom (field0, field1) -> SemanticJson.union "CExpr" "TypedAtom" [aNF_atom field0; SemanticAST.semanticType field1]
 | InstrumentedANF.Prim (field0, field1, field2) -> SemanticJson.union "CExpr" "Prim" [aNF_binOp field0; aNF_atom field1; aNF_atom field2]
 | InstrumentedANF.UnaryPrim (field0, field1) -> SemanticJson.union "CExpr" "UnaryPrim" [aNF_unaryOp field0; aNF_atom field1]
 | InstrumentedANF.IfValue (field0, field1, field2) -> SemanticJson.union "CExpr" "IfValue" [aNF_atom field0; aNF_atom field1; aNF_atom field2]
 | InstrumentedANF.Call (field0, field1) -> SemanticJson.union "CExpr" "Call" [functionId field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.BorrowedCall (field0, field1) -> SemanticJson.union "CExpr" "BorrowedCall" [functionId field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.TailCall (field0, field1) -> SemanticJson.union "CExpr" "TailCall" [functionId field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.IndirectCall (field0, field1) -> SemanticJson.union "CExpr" "IndirectCall" [aNF_atom field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.IndirectTailCall (field0, field1) -> SemanticJson.union "CExpr" "IndirectTailCall" [aNF_atom field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.ClosureAlloc (field0, field1) -> SemanticJson.union "CExpr" "ClosureAlloc" [functionId field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.ClosureCall (field0, field1) -> SemanticJson.union "CExpr" "ClosureCall" [aNF_atom field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.ClosureTailCall (field0, field1) -> SemanticJson.union "CExpr" "ClosureTailCall" [aNF_atom field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.TupleAlloc (field0) -> SemanticJson.union "CExpr" "TupleAlloc" [list (fun item -> aNF_atom item) field0]
 | InstrumentedANF.TupleGet (field0, field1) -> SemanticJson.union "CExpr" "TupleGet" [aNF_atom field0; int32 field1]
 | InstrumentedANF.RecordAlloc (field0, field1) -> SemanticJson.union "CExpr" "RecordAlloc" [aNF_recordDescriptor field0; list (fun item -> aNF_atom item) field1]
 | InstrumentedANF.RecordGet (field0, field1, field2) -> SemanticJson.union "CExpr" "RecordGet" [aNF_recordDescriptor field0; aNF_atom field1; int32 field2]
 | InstrumentedANF.RecordClone (field0, field1, field2) -> SemanticJson.union "CExpr" "RecordClone" [aNF_recordDescriptor field0; aNF_atom field1; list (fun item -> aNF_atom item) field2]
 | InstrumentedANF.RecordReuse (field0, field1, field2, field3) -> SemanticJson.union "CExpr" "RecordReuse" [aNF_recordDescriptor field0; aNF_recordDescriptor field1; aNF_atom field2; list (fun item -> aNF_atom item) field3]
 | InstrumentedANF.StringConcat (field0, field1, field2) -> SemanticJson.union "CExpr" "StringConcat" [aNF_atom field0; aNF_atom field1; list (fun item -> aNF_atom item) field2]
 | InstrumentedANF.CanonicalBufferEq (field0, field1, field2) -> SemanticJson.union "CExpr" "CanonicalBufferEq" [memoryModel_canonicalBufferKind field0; aNF_atom field1; aNF_atom field2]
 | InstrumentedANF.RefCountInc (field0, field1, field2, field3) -> SemanticJson.union "CExpr" "RefCountInc" [aNF_atom field0; int32 field1; memoryModel_rcKind field2; option (fun item -> memoryModel_rcMetadata item) field3]
 | InstrumentedANF.RefCountDec (field0, field1, field2, field3) -> SemanticJson.union "CExpr" "RefCountDec" [aNF_atom field0; int32 field1; memoryModel_rcKind field2; option (fun item -> memoryModel_rcMetadata item) field3]
 | InstrumentedANF.Print (field0, field1) -> SemanticJson.union "CExpr" "Print" [aNF_atom field0; SemanticAST.semanticType field1]
 | InstrumentedANF.StdoutWrite (field0, field1) -> SemanticJson.union "CExpr" "StdoutWrite" [aNF_atom field0; boolean field1]
 | InstrumentedANF.StdinReadLine -> SemanticJson.union "CExpr" "StdinReadLine" []
 | InstrumentedANF.RuntimeError (field0) -> SemanticJson.union "CExpr" "RuntimeError" [SemanticJson.string field0]
 | InstrumentedANF.RuntimeErrorString (field0) -> SemanticJson.union "CExpr" "RuntimeErrorString" [aNF_atom field0]
 | InstrumentedANF.FileReadBlob (field0) -> SemanticJson.union "CExpr" "FileReadBlob" [aNF_atom field0]
